package heybox

// sign_test.go — the signer pinned against reference vectors
// generated by running the ORIGINAL JavaScript implementations on
// fixed inputs (smoke refs/gen.mjs, 2026-11-13): RSSHub util.ts and
// WenfuRainbow signature.ts each signed the four endpoint paths at
// ts=1760000000 with the fixed nonce below, and the Go ports must
// reproduce those outputs digit for digit. A red here means one of
// exactly two things: a mistranscribed constant (fix the port), or
// upstream changed the algorithm (flip the transport's shape — the
// stop-loss ladder).

import (
	"fmt"
	"testing"
	"time"
)

// refVectors are the smoke's self-check table, verbatim
// (.scratch/m5-heybox/smoke/main.go): every list/detail/comment
// endpoint family the source talks to.
var refVectors = []struct {
	path  string
	ts    int64
	nonce string
	a, b  string
}{
	{"/bbs/app/feeds/news", 1760000000, "ABCDEF0123456789ABCDEF0123456789", "826NB12", "X03Y761"},
	{"/bbs/app/link/tree", 1760000000, "ABCDEF0123456789ABCDEF0123456789", "KP9HN82", "X03Y761"},
	{"/bbs/app/comment/sub/comments", 1760000000, "ABCDEF0123456789ABCDEF0123456789", "JBAOM94", "X03Y761"},
	{"/bbs/app/topic/feeds", 1760000000, "ABCDEF0123456789ABCDEF0123456789", "PKAJQ64", "X03Y761"},
}

func TestSignAMatchesReferenceVectors(t *testing.T) {
	for _, v := range refVectors {
		if got := signA(v.path, v.ts, v.nonce); got != v.a {
			t.Errorf("signA(%q) = %q, want reference %q", v.path, got, v.a)
		}
	}
}

func TestSignBMatchesReferenceVectors(t *testing.T) {
	for _, v := range refVectors {
		if got := signB(v.path, v.ts, v.nonce); got != v.b {
			t.Errorf("signB(%q) = %q, want reference %q", v.path, got, v.b)
		}
	}
}

// TestCanonicalPathCollapses: the signature covers the canonical path
// — double slashes and a missing lead both fold to the same signed
// string, which is what makes hand-built endpoint paths safe.
func TestCanonicalPathCollapses(t *testing.T) {
	for _, c := range [][2]string{
		{"/bbs/app/feeds", "/bbs/app/feeds/"},
		{"bbs//app/feeds", "/bbs/app/feeds/"},
	} {
		if got, want := canonicalPath(c[0]), canonicalPath(c[1]); got != want {
			t.Errorf("canonicalPath(%q) = %q, want %q", c[0], got, want)
		}
	}
}

// TestSignTripleCarriesShapeBinding: the triple rides the shape it
// was signed with — the same path/time/nonce under the two shapes
// produce different hkeys and different version strings, the pairing
// the server enforces (crossed pairs answer 非法请求).
func TestSignTripleCarriesShapeBinding(t *testing.T) {
	now := time.Unix(1760000000, 0)
	nonce := "ABCDEF0123456789ABCDEF0123456789"
	hkA := shapeWebV3.sign("/bbs/app/feeds", now.Unix(), nonce)
	hkB := shapeWebV4.sign("/bbs/app/feeds", now.Unix(), nonce)
	if hkA == hkB {
		t.Errorf("variant A and B agreed on %q — the vectors say they must not", hkA)
	}
	if shapeWebV3.version == shapeWebV4.version {
		t.Error("the two shapes carry the same version string — the binding is broken")
	}
}

// TestNewNonceShape: the nonce is a 32-char uppercase hex string, and
// two calls never agree (fresh randomness per request is protocol).
func TestNewNonceShape(t *testing.T) {
	n1, err := newNonce(1760000000)
	if err != nil {
		t.Fatalf("newNonce: %v", err)
	}
	if len(n1) != 32 {
		t.Fatalf("nonce len = %d, want 32", len(n1))
	}
	for _, r := range n1 {
		if !(r >= '0' && r <= '9' || r >= 'A' && r <= 'F') {
			t.Fatalf("nonce %q is not uppercase hex", n1)
		}
	}
	n2, _ := newNonce(1760000000)
	if n1 == n2 {
		t.Fatal("two nonces agreed — randomness is part of the protocol")
	}
}

// TestSignTripleRoundTrip is the smoke's own usage: sign, then verify
// the pieces the query carries are exactly the pieces signed with.
func TestSignTripleRoundTrip(t *testing.T) {
	hkey, nonce, ts, err := signTriple(shapeWebV3, "/bbs/app/feeds", time.Unix(1760000001, 0))
	if err != nil {
		t.Fatalf("signTriple: %v", err)
	}
	if want := signA("/bbs/app/feeds", ts, nonce); hkey != want {
		t.Errorf("hkey = %q, want signA over the returned triple %q", hkey, want)
	}
	if ts != 1760000001 {
		t.Errorf("ts = %d, want the given clock", ts)
	}
	_ = fmt.Sprint(nonce)
}
